alter table public.lgpd_access_request_log add column if not exists prazo_em timestamptz,add column if not exists responsavel_id uuid references auth.users(id),add column if not exists base_legal text,add column if not exists evidencia text,add column if not exists updated_at timestamptz not null default now();update public.lgpd_access_request_log set prazo_em=requested_at+interval '15 days' where prazo_em is null;alter table public.lgpd_access_request_log alter column prazo_em set default(now()+interval '15 days');
create table if not exists public.platform_retention_policies(id uuid primary key default gen_random_uuid(),categoria text not null unique,retencao_meses integer not null check(retencao_meses between 1 and 360),base_legal text not null,ativo boolean not null default true,updated_at timestamptz not null default now(),updated_by uuid references auth.users(id));alter table public.platform_retention_policies enable row level security;
create policy "plataforma le solicitacoes lgpd" on public.lgpd_access_request_log for select to authenticated using(is_platform_admin());create policy "plataforma acompanha solicitacoes lgpd" on public.lgpd_access_request_log for update to authenticated using(is_platform_admin()) with check(is_platform_admin());create policy "plataforma gerencia retencao" on public.platform_retention_policies for all to authenticated using(is_platform_admin()) with check(is_platform_admin() and updated_by=auth.uid());
insert into public.platform_retention_policies(categoria,retencao_meses,base_legal)values('prontuario',240,'CFM 1.821/2007 e obrigação legal'),('financeiro',60,'Obrigação fiscal e defesa de direitos'),('auditoria',60,'LGPD art. 37 e segurança')on conflict(categoria)do nothing;

